    "Mwinda Market a été fondée avec une mission simple : rendre la technologie de pointe accessible à tous les Africains. Mwinda Market réunit des boutiques et des acheteurs sur une même place de marché, avec un lancement en République démocratique du Congo avant l'ouverture aux autres pays du continent.": "Mwinda Market ilianzishwa na dhamira rahisi: kufanya teknolojia ya kisasa ipatikane kwa Waafrika wote. Mwinda Market inakutanisha maduka na wanunuzi katika soko moja, ikianza katika Jamhuri ya Kidemokrasia ya Kongo kabla ya kufunguliwa kwa nchi nyingine za bara.",
