    "La commission est prélevée sur chaque vente livrée. Les plans payants sont valables 3 mois : après votre demande, notre équipe vous indique comment régler l'abonnement et active le plan dès réception. À la fin de la période, la boutique repasse au plan gratuit.": "佣金从每笔已送达的订单中扣除。付费方案有效期为3个月：提交申请后，我们的团队会告知您如何支付订阅费用，并在收到款项后激活方案。期满后，店铺将恢复为免费方案。",
