    "Mwinda Market a été fondée avec une mission simple : rendre la technologie de pointe accessible à tous les Africains. Mwinda Market réunit des boutiques et des acheteurs sur une même place de marché, avec un lancement en République démocratique du Congo avant l'ouverture aux autres pays du continent.": "Mwinda Market se fundó con una misión sencilla: hacer que la tecnología de vanguardia sea accesible para todos los africanos. Mwinda Market reúne tiendas y compradores en un mismo mercado, con un lanzamiento en la República Democrática del Congo antes de abrirse a otros países del continente.",
