    "Jusqu'à 40% de réduction sur l'audio": "Hasta un 40% de descuento en audio",
    "La commission est prélevée sur chaque vente livrée. Les plans payants sont valables 3 mois : après votre demande, notre équipe vous indique comment régler l'abonnement et active le plan dès réception. À la fin de la période, la boutique repasse au plan gratuit.": "La comisión se descuenta de cada venta entregada. Los planes de pago son válidos por 3 meses: tras tu solicitud, nuestro equipo te indicará cómo pagar la suscripción y activará el plan al recibir el pago. Al terminar el período, la tienda vuelve al plan gratuito.",
    "Lampes de bureau": "Lámparas de escritorio",
    "Le suivi est réservé au client qui a passé la commande.": "El seguimiento está reservado al cliente que hizo el pedido.",
    "Les prix sont en dollars par trimestre (la monnaie locale n’est affichée qu’à titre indicatif). La commission s'applique aux commandes passées après la modification.": "Los precios están en dólares por trimestre (la moneda local se muestra solo como referencia). La comisión se aplica a los pedidos realizados después del cambio.",
